/* From Uiverse.io by Gianluks90 - Tags: notification */
.__UIV_SCOPE__ .notification {
  width: 255px;
  height: 60px;
  background: white;
  border-radius: 25px;
  display: flex;
  justify-content: space-evenly;
  align-items: center;
}

.__UIV_SCOPE__ .icon {
  height: 40px;
  width: 40px;
  border-radius: 20px;
  background-color: rgb(236, 236, 236);
  display: flex;
  justify-content: center;
  align-items: center;
  padding-top: 2px;
}

.__UIV_SCOPE__ .message-container {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .title {
  padding: 2px;
  text-transform: uppercase;
  color: black;
  font-weight: 600;
}

.__UIV_SCOPE__ .message {
  padding: 2px;
  color: black;
  font-size: small;
}

.__UIV_SCOPE__ .gradient-border {
  --borderSize: 3px;
  position: relative;
  border-radius: var(--borderSize);
}

.__UIV_SCOPE__ .gradient-border:after {
  content: '';
  position: absolute;
  top: calc(-1 * var(--borderSize));
  left: calc(-1 * var(--borderSize));
  height: calc(100% + var(--borderSize) * 2);
  width: calc(100% + var(--borderSize) * 2);
  background: linear-gradient(75deg, #E50000, #FF8D00, #FFEE00, #008121, #004CFF, #760188);
  border-radius: calc(2 * var(--borderSize));
  z-index: -1;
  animation: gradientAnimation 4s ease alternate infinite;
  background-size: 300% 300%;
}

@keyframes gradientAnimation {
  0% {
    background-position: 0% 50%;
  }

  50% {
    background-position: 100% 50%;
  }

  100% {
    background-position: 0% 50%;
  }
}
